import { strict as assert } from 'node:assert'
import { describe, it } from 'node:test'
import { nameProblem, ssidFromAirport } from './network-name.js'

const NAMED =
  ''
const BYTES_ONLY =
  ''
const BLANK =
  ''

const NO_NAME_KEYS =
  ''

const airport = ({ visible = '', record = null }) =>
  [
    '<dictionary> {',
    '  BSSID : <data> 0x020000000000',
    ...(record ? [`  CachedScanRecord : <data> 0x${record}`] : []),
    '  SSID : <data> 0x00',
    `  SSID_STR : ${visible}`,
    '}',
  ].join('\n')

describe('ssidFromAirport', () => {
  it('takes the name macOS shows when it is not redacted', () => {
    assert.equal(ssidFromAirport(airport({ visible: 'Office', record: BLANK })), 'Office')
  })

  it('reads the spelled out name from the cached scan record when the live one is blanked', () => {
    assert.equal(ssidFromAirport(airport({ record: NAMED })), 'Kitchen Wi-Fi')
  })

  it('falls back to the raw name bytes when the record has no spelled out name', () => {
    assert.equal(ssidFromAirport(airport({ record: BYTES_ONLY })), 'Pixel hotspot')
  })

  it('gives up when neither the live name nor the record has one', () => {
    assert.equal(ssidFromAirport(airport({ record: BLANK })), null)
    assert.equal(ssidFromAirport(airport({ record: NO_NAME_KEYS })), null)
    assert.equal(ssidFromAirport(airport({})), null)
  })

  it('gives up on a record it cannot parse', () => {
    assert.equal(ssidFromAirport(airport({ record: 'deadbeef' })), null)
  })
})

describe('nameProblem', () => {
  it('says why a Wi-Fi network has no readable name', () => {
    assert.equal(nameProblem(airport({ record: BLANK })), 'scan record has no name')
    assert.equal(nameProblem(airport({})), 'no scan record')
  })

  it('has nothing to say when the name was read or the interface is not Wi-Fi', () => {
    assert.equal(nameProblem(airport({ record: NAMED })), null)
    assert.equal(nameProblem('  No such key\n'), null)
  })
})
